using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchData(
        HttpClient httpClient,
        ILogger<IMcpServer> logger,
        [Description("The API path to query, e.g. /users/1")] string path,
        CancellationToken cancellationToken)
    {
        logger.LogInformation("Fetching data from {Path}", path);

        var response = await httpClient.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks an LLM to summarize the given text.")]
    public static ChatMessage Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional maximum length hint, e.g. '2 sentences'")] string? maxLength = null)
    {
        var instruction = maxLength is not null
            ? $"Summarize the following text in {maxLength}:"
            : "Summarize the following text concisely:";

        return new ChatMessage(Role.User, $"{instruction}\n\n{text}");
    }
}

